63	/**
64	 * User callback is passed from flb_output(ctx, output, callback)
65	 *
66	 *  The prototype of callback should be
67	 *   int (*callback)(void* data, size_t size );
68	 *    @param   data  The data which comes from input plugin.
69	 *    @param   size  The size of data.
70	 *    @return  success ? 0 : negative value
71	 *
72	 */
73	static int out_lib_init(struct flb_output_instance *ins,
74	                        struct flb_config *config,
75	                        void *data)
76	{
77	    struct flb_out_lib_config *ctx = NULL;
78	    struct flb_lib_out_cb *cb_data = data;
79	    (void) config;
80	
81	    ctx = flb_calloc(1, sizeof(struct flb_out_lib_config));
82	    if (ctx == NULL) {
83	        flb_errno();
84	        return -1;
85	    }
86	    ctx->ins = ins;
87	
88	    if (cb_data) {
89	        /* Set user callback and data */
90	        ctx->cb_func = cb_data->cb;
91	        ctx->cb_data = cb_data->data;
92	    }
93	    else {
94	        flb_plg_error(ctx->ins, "Callback is not set");
95	        flb_free(ctx);
96	        return -1;
97	    }
98	
99	    configure(ctx, ins);
100	    flb_output_set_context(ins, ctx);
101	
102	    return 0;
103	}
