1889	
1890	    if (request->method != MK_METHOD_POST) {
1891	        flb_sds_destroy(tag);
1892	        mk_mem_free(uri);
1893	        send_response(conn, 400, "error: invalid HTTP method\n");
1894	        return -1;
1895	    }
1896	
1897	    original_data = request->data.data;
1898	    original_data_size = request->data.len;
1899	
1900	    /* check if the request comes with chunked transfer encoding */
1901	    if (mk_http_parser_is_content_chunked(&session->parser)) {
