60	void wait_with_timeout(uint32_t timeout_ms, int *output_num)
61	{
62	    struct flb_time start_time;
63	    struct flb_time end_time;
64	    struct flb_time diff_time;
65	    uint64_t elapsed_time_flb = 0;
66	
67	    flb_time_get(&start_time);
68	
69	    while (true) {
70	        *output_num = get_output_num();
71	
72	        if (*output_num > 0) {
73	            break;
74	        }
75	
76	        flb_time_msleep(100);
77	        flb_time_get(&end_time);
78	        flb_time_diff(&end_time, &start_time, &diff_time);
79	        elapsed_time_flb = flb_time_to_nanosec(&diff_time) / 1000000;
80	
81	        if (elapsed_time_flb > timeout_ms) {
82	            flb_warn("[timeout] elapsed_time: %ld", elapsed_time_flb);
83	            // Reached timeout.
84	            break;
85	        }
86	    }
